#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <queue>
#include <set>
#include <sstream>
#include <string>
#include <vector>
using namespace std;struct GradeRecord{int studentId;string courseId;double grade=-1;string status="In Progress";};class Course{string id,name,schedule;int credits,capacity;vector<int>enrolled;queue<int>waitlist;vector<string>prereqs;public:Course(string i="",string n="",int cr=3,int cap=30,string sch=""):id(move(i)),name(move(n)),schedule(move(sch)),credits(cr),capacity(cap){}const string&getId()const{return id;}const string&getSchedule()const{return schedule;}int getCredits()const{return credits;}bool has(int sid)const{return find(enrolled.begin(),enrolled.end(),sid)!=enrolled.end();}void addPrereq(string p){prereqs.push_back(move(p));}const auto&requirements()const{return prereqs;}bool enroll(int sid){if(has(sid))return false;if((int)enrolled.size()>=capacity){waitlist.push(sid);return false;}enrolled.push_back(sid);return true;}bool drop(int sid){auto it=find(enrolled.begin(),enrolled.end(),sid);if(it==enrolled.end())return false;enrolled.erase(it);if(!waitlist.empty()){enrolled.push_back(waitlist.front());waitlist.pop();}return true;}void show()const{cout<<id<<" | "<<name<<" | "<<credits<<" cr | "<<schedule<<" | "<<enrolled.size()<<'/'<<capacity<<'\n';}string data()const{return id+"|"+name+"|"+to_string(credits)+"|"+to_string(capacity)+"|"+schedule;}};class Registrar{vector<Course>courses;vector<GradeRecord>grades;map<int,set<string>>completed;Course*findCourse(const string&id){for(auto&c:courses)if(c.getId()==id)return&c;return nullptr;}bool conflict(int sid,const string&s)const{for(auto&g:grades)if(g.studentId==sid&&g.status=="In Progress")for(auto&c:courses)if(c.getId()==g.courseId&&c.getSchedule()==s)return true;return false;}public:void load(){ifstream in("courses.txt");string l;while(getline(in,l)){stringstream s(l);string a,b,c,d,e;getline(s,a,'|');getline(s,b,'|');getline(s,c,'|');getline(s,d,'|');getline(s,e);if(!a.empty())courses.emplace_back(a,b,stoi(c),stoi(d),e);}}void save()const{ofstream o("courses.txt");for(auto&c:courses)o<<c.data()<<'\n';ofstream g("grades.txt");for(auto&x:grades)g<<x.studentId<<'|'<<x.courseId<<'|'<<x.grade<<'|'<<x.status<<'\n';}void create(){string id,n,s;int cr,cap;cin>>id;cin>>ws;getline(cin,n);cin>>cr>>cap>>s;if(!findCourse(id))courses.emplace_back(id,n,cr,cap,s);}void list()const{for(auto&c:courses)c.show();}void prereq(){string id,p;cin>>id>>p;if(auto*c=findCourse(id))c->addPrereq(p);}void enroll(){int sid;string cid;cin>>sid>>cid;auto*c=findCourse(cid);if(!c)return;for(auto&p:c->requirements())if(!completed[sid].count(p)){cout<<"Missing prerequisite "<<p<<'\n';return;}if(conflict(sid,c->getSchedule())){cout<<"Schedule conflict\n";return;}if(c->enroll(sid)){grades.push_back({sid,cid,-1,"In Progress"});cout<<"Enrolled\n";}else cout<<"Full/waitlisted\n";}void drop(){int sid;string cid;cin>>sid>>cid;if(auto*c=findCourse(cid);c&&c->drop(sid))for(auto&g:grades)if(g.studentId==sid&&g.courseId==cid&&g.status=="In Progress")g.status="Withdrawn";}void grade(){int sid;string cid;double x;cin>>sid>>cid>>x;if(x<0||x>100)return;for(auto&g:grades)if(g.studentId==sid&&g.courseId==cid&&g.status=="In Progress"){g.grade=x;g.status="Completed";completed[sid].insert(cid);}}void transcript(){int sid;cin>>sid;double pts=0;int crs=0;for(auto&g:grades)if(g.studentId==sid){cout<<g.courseId<<" | "<<g.status<<" | "<<g.grade<<'\n';if(g.status=="Completed"){auto*c=findCourse(g.courseId);int cr=c?c->getCredits():3;double p=g.grade>=90?4:g.grade>=80?3:g.grade>=70?2:g.grade>=60?1:0;pts+=p*cr;crs+=cr;}}cout<<"GPA "<<(crs?pts/crs:0)<<'\n';}void run(){load();for(;;){cout<<"\nCourse Registration\n1 Create 2 List 3 Prerequisite 4 Enroll 5 Drop 6 Grade 7 Transcript 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)create();else if(c==2)list();else if(c==3)prereq();else if(c==4)enroll();else if(c==5)drop();else if(c==6)grade();else if(c==7)transcript();save();}}};int main(){Registrar{}.run();}
